import sailpoint.object.*;
  String pkid=identity.getAttribute("primaryKid");
  if(pkid !=null)
  {
  	//identity.setAttribute("primaryKid",pkid);
    //System.out.println("primaryKid: "+ pkid);
        return pkid;
  }
  else
  {
    String fn=identity.getAttribute("firstname");
    fn=fn.substring(0,1);
    String r=String.valueOf(Math.random());
    r=r.substring(2,6);
    //identity.setAttribute("primaryKid",(fn+r));
     //System.out.println("primaryKid: "+(fn+r));
      return (fn+r);

  }
